    // (Windows 用户配置目录已按用户 ACL 隔离,此处不额外处理。真·防同用户恶意软件仍需 OS 钥匙串
    //  级静态加密 —— 见 security 备忘,作为后续带真机验证的独立改动。)
    #[cfg(unix)]
