    assert.equal(files.length, 1);
    const row = JSON.parse(readFileSync(join(dir, "2026-10-14", files[0]), "utf8"));
    assert.equal(row.legacyMessageId, "msg-1");
    assert.equal(row.sessionId, "session-a");
