    fs::read_to_string(path).map(|s| s.lines().filter_map(|line| serde_json::from_str(line).ok()).collect()).unwrap_or_default()
}
fn until(mut condition: impl FnMut() -> bool) -> Result<(), String> {
    let end = Instant::now() + Duration::from_secs(5);
