306: +  async handle(provider: string, operation: string, input?: string): Promise<Snapshot> {
307: +    if (!["anthropic", "openai-codex"].includes(provider)) throw new DaemonError("OAUTH_UNSUPPORTED", "Unsupported OAuth provider");
